import React, { useEffect, useMemo } from 'react'
import { useDispatch, useSelector } from 'react-redux'
import { getProductsList } from '../actions/productActions'
import Message from '../components/Message'
import { Spinner } from 'react-bootstrap'
import Product from '../components/Product'
import { useHistory } from 'react-router-dom'
import { CREATE_PRODUCT_RESET } from '../constants'


function ProductsListPage() {

    const history = useHistory()
    const dispatch = useDispatch()


    // =========================================
    // GET SEARCH + CATEGORY FROM URL
    // =========================================

    const params = new URLSearchParams(
        history.location.search
    )

    const searchTerm =
        params.get('searchTerm') || ''

    const category =
        params.get('category') || ''


    // =========================================
    // REDUX PRODUCTS
    // =========================================

    const productsListReducer = useSelector(
        state => state.productsListReducer
    )

    const {
        loading,
        error,
        products = []
    } = productsListReducer


    // =========================================
    // LOAD PRODUCTS
    // =========================================

    useEffect(() => {

        dispatch(getProductsList())

        dispatch({
            type: CREATE_PRODUCT_RESET
        })

    }, [dispatch])


    // =========================================
    // CATEGORY MAPPING
    // =========================================

    const getCategory = (product) => {

        const cat = (
            product.category || ''
        ).toLowerCase().trim()


        // ELECTRONICS

        if (
            cat === 'laptops' ||
            cat === 'smartphones' ||
            cat === 'tablets' ||
            cat === 'mobile-accessories'
        ) {
            return 'Electronics'
        }


        // MEN

        if (
            cat === 'mens-shirts' ||
            cat === 'mens-shoes'
        ) {
            return 'Men'
        }


        // WATCHES

        if (
            cat === 'mens-watches' ||
            cat === 'womens-watches'
        ) {
            return 'Watches'
        }


        // WOMEN

        if (
            cat === 'tops' ||
            cat === 'womens-dresses'
        ) {
            return 'Women'
        }


        // BEAUTY

        if (
            cat === 'beauty' ||
            cat === 'fragrances' ||
            cat === 'skin-care' ||
            cat === 'sunglasses'
        ) {
            return 'Beauty'
        }


        // HOME & KITCHEN

        if (
            cat === 'furniture' ||
            cat === 'home-decoration' ||
            cat === 'kitchen-accessories'
        ) {
            return 'Home & Kitchen'
        }


        // GROCERIES

        if (
            cat === 'groceries'
        ) {
            return 'Groceries'
        }


        // SPORTS

        if (
            cat === 'sports-accessories'
        ) {
            return 'Sports'
        }


        // FOOTWEAR

        if (
            cat === 'mens-shoes' ||
            cat === 'womens-shoes'
        ) {
            return 'Footwear'
        }


        // JEWELLERY

        if (
            cat === 'jewellery'
        ) {
            return 'Jewellery'
        }


        // BAGS

        if (
            cat === 'bags' ||
            cat === 'womens-bags'
        ) {
            return 'Bags'
        }


        // KIDS

        if (
            cat === 'kids' ||
            cat === 'toys'
        ) {
            return 'Kids & Toys'
        }


        // MOTORCYCLE

        if (
            cat === 'motorcycle'
        ) {
            return 'Motorcycle'
        }


        // OTHER

        return 'Other'
    }


    // =========================================
    // DEBUG
    // =========================================

    useEffect(() => {

        if (products.length > 0) {

            console.log(
                'TOTAL PRODUCTS:',
                products.length
            )


            console.log(
                'PRODUCT DATA:',
                products.map(product => ({
                    name: product.name,
                    category: product.category,
                    shopEaseCategory:
                        getCategory(product)
                }))
            )


            console.log(
                'CATEGORY COUNTS:',
                products.reduce(
                    (result, product) => {

                        const cat =
                            getCategory(product)

                        result[cat] =
                            (result[cat] || 0) + 1

                        return result

                    },
                    {}
                )
            )

        }

    }, [products])


    // =========================================
    // SEARCH + CATEGORY FILTER
    // =========================================

    const filteredProducts = useMemo(() => {

        const search =
            searchTerm
                .toLowerCase()
                .trim()


        return products.filter((product) => {

            const productName =
                (product.name || '')
                    .toLowerCase()


            const description =
                (product.description || '')
                    .toLowerCase()


            const productCategory =
                (product.category || '')
                    .toLowerCase()


            const shopEaseCategory =
                getCategory(product)
                    .toLowerCase()


            // =====================================
            // SEARCH
            // =====================================

            const matchesSearch =

                !search ||

                productName.includes(search) ||

                description.includes(search) ||

                productCategory.includes(search) ||

                shopEaseCategory.includes(search)


            // =====================================
            // CATEGORY
            // =====================================

            const matchesCategory =

                !category ||

                category === 'Popular' ||

                getCategory(product) === category


            return (
                matchesSearch &&
                matchesCategory
            )

        })

    }, [
        products,
        searchTerm,
        category
    ])


    // =========================================
    // SEARCH HANDLER
    // =========================================

    const handleSearch = (event) => {

        const value =
            event.target.value


        if (value.trim()) {

            history.push(
                `/?searchTerm=${encodeURIComponent(value)}`
            )

        } else {

            history.push('/')

        }

    }


    // =========================================
    // RENDER
    // =========================================

    return (

        <div className="shopease-home">


            {/* =========================================
                HERO
            ========================================= */}

            {!searchTerm && !category && (

                <section className="hero-section">

                    <div className="hero-overlay">

                        <div className="hero-content">

                            <span className="hero-small-title">
                                WELCOME TO SHOPEASE
                            </span>


                            <h1>
                                Style That Fits You
                            </h1>


                            <p>
                                Discover trending fashion,
                                accessories and everyday essentials
                                at amazing prices.
                            </p>


                            <div className="hero-buttons">

                                <button
                                    className="hero-primary-btn"
                                    onClick={() =>
                                        document
                                            .getElementById(
                                                'products-section'
                                            )
                                            ?.scrollIntoView({
                                                behavior: 'smooth'
                                            })
                                    }
                                >
                                    Shop Now
                                </button>


                                <button
                                    className="hero-secondary-btn"
                                    onClick={() =>
                                        document
                                            .getElementById(
                                                'products-section'
                                            )
                                            ?.scrollIntoView({
                                                behavior: 'smooth'
                                            })
                                    }
                                >
                                    Explore Products
                                </button>

                            </div>

                        </div>

                    </div>

                </section>

            )}


            {/* =========================================
                BENEFITS
            ========================================= */}

            {!searchTerm && !category && (

                <section className="benefits-section">


                    <div className="benefit-card">

                        <div className="benefit-icon">
                            🚚
                        </div>

                        <div>
                            <h5>
                                Fast Delivery
                            </h5>

                            <p>
                                Delivery across India
                            </p>
                        </div>

                    </div>


                    <div className="benefit-card">

                        <div className="benefit-icon">
                            💵
                        </div>

                        <div>
                            <h5>
                                Cash on Delivery
                            </h5>

                            <p>
                                Pay when your order arrives
                            </p>
                        </div>

                    </div>


                    <div className="benefit-card">

                        <div className="benefit-icon">
                            🔄
                        </div>

                        <div>
                            <h5>
                                Easy Returns
                            </h5>

                            <p>
                                Simple return policy
                            </p>
                        </div>

                    </div>


                    <div className="benefit-card">

                        <div className="benefit-icon">
                            🔒
                        </div>

                        <div>
                            <h5>
                                Secure Payments
                            </h5>

                            <p>
                                100% secure checkout
                            </p>
                        </div>

                    </div>

                </section>

            )}


            {/* =========================================
                SEARCH
            ========================================= */}

            <section className="homepage-search">

                <div className="search-heading">

                    <h2>
                        Find Your Favourite Products
                    </h2>

                    <p>
                        Search from our collection
                    </p>

                </div>


                <div className="modern-search-box">

                    <span>
                        🔍
                    </span>


                    <input
                        type="text"
                        value={searchTerm}
                        onChange={handleSearch}
                        placeholder="Search for products, brands and more"
                    />


                    {searchTerm && (

                        <button
                            onClick={() =>
                                history.push('/')
                            }
                        >
                            ✕
                        </button>

                    )}

                </div>

            </section>


            {/* =========================================
                PRODUCTS
            ========================================= */}

            <section
                id="products-section"
                className="products-section"
            >


                <div className="products-heading">

                    <div>

                        <h2>

                            {searchTerm

                                ? `Search results for "${searchTerm}"`

                                : category
                                    ? `${category} Products`
                                    : 'Popular Products'

                            }

                        </h2>


                        <p>
                            {filteredProducts.length}
                            {' '}
                            products found
                        </p>

                    </div>

                </div>


                {/* ERROR */}

                {error && (

                    <Message variant="danger">
                        {error}
                    </Message>

                )}


                {/* LOADING */}

                {loading && (

                    <div className="loading-container">

                        <Spinner animation="border" />

                        <p>
                            Getting products...
                        </p>

                    </div>

                )}


                {/* PRODUCT LIST */}

                {!loading && (

                    filteredProducts.length === 0

                        ? (

                            <div className="empty-products">

                                <div className="empty-icon">
                                    🛍️
                                </div>


                                <h3>
                                    No products found
                                </h3>


                                <p>
                                    Try searching for another
                                    product or category.
                                </p>


                                <button
                                    onClick={() =>
                                        history.push('/')
                                    }
                                >
                                    View All Products
                                </button>

                            </div>

                        )

                        : (

                            <div className="product-grid">

                                {filteredProducts.map(
                                    (product) => (

                                        <Product
                                            key={product.id}
                                            product={product}
                                        />

                                    )
                                )}

                            </div>

                        )

                )}

            </section>


            {/* =========================================
                SHOPPING BANNER
            ========================================= */}

            {!searchTerm && !category && (

                <section className="shopping-banner">

                    <div>

                        <h2>
                            Shop smarter with ShopEase
                        </h2>


                        <p>
                            Great products. Great prices.
                            Delivered to your doorstep.
                        </p>

                    </div>


                    <button
                        onClick={() =>
                            document
                                .getElementById(
                                    'products-section'
                                )
                                ?.scrollIntoView({
                                    behavior: 'smooth'
                                })
                        }
                    >
                        Start Shopping
                    </button>

                </section>

            )}

        </div>

    )
}


export default ProductsListPage
